INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1001, 0, 0, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 0, 0, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 2, 1, "お！\nあそこに困ってそうな人発見！", 1, "春咲 ひより", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1002, 0, 0, "わ、わたし、\nなに言ってるんだろ\nあはは…", 0, 0, "みんなみたいに\nわたしも強くならなきゃ", 2, 1, "大切な人を\n守れるようになりたい…って", 1, "草野 優衣", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1003, 0, 0, "少しは磨かれると思いますよ。", 0, 0, "フェンシングを始めてみては？", 2, 1, "キミに必要な集中力と感性が", 1, "士条 怜", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1004, 0, 0, "みそぎはねぇ、\nかくれんぼやりたい！", 0, 0, "ねぇ、にいちゃん！", 2, 1, "今日はなにして遊ぶ？", 1, "穂高 みそぎ", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1006, 0, 0, "私といっしょに…\nいかない？", 0, 0, "風宮あかりです", 2, 1, "ねぇ…", 1, "風宮 あかり", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1007, 0, 0, "食べ物の恨みは怖いのー", 0, 0, "出雲宮子なのー", 2, 1, "プリンたべたいのー", 1, "出雲 宮子", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1008, 0, 0, "いいよ。\n見られることは運命さ…", 0, 0, "ボクは虹村雪。", 2, 1, "キミもボクの美貌に\n吸い寄せられたんだね。", 1, "虹村 雪", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1009, 0, 0, "人呼んで「疾風の冥姫」!!", 0, 0, "フッ…聞いて後悔するがいい！", 2, 1, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1, "柊杏奈", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1010, 0, 0, "ほんまおおきにやわ～♪", 0, 0, "マホマホ王国のプリンセス、\nまほ姫どす", 2, 1, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1, "姫宮 真歩", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1011, 0, 0, "ここで会ったが\n100年目～！", 0, 0, "衣之咲璃乃です！", 2, 1, "生き別れたお兄ちゃんを探して\n三千世界！", 1, "衣之咲 璃乃", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1012, 0, 0, "…って、お願い！\n誰にも言わないでおいて～！", 0, 0, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 2, 1, "ち、超能力って…\n何のことかな～？", 1, "柏崎 初音", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1016, 0, 0, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 0, 0, "ちょす！\n美波鈴奈だよ～♪", 2, 1, "一応カリスマ読モJKやってまっす！", 1, "美波 鈴奈", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1017, 0, 0, "でも、沖縄もとってもいいとこさー", 0, 0, "はいたーい。\n喜屋武香織さー。", 2, 1, "東京は遊園地みたいなところさー", 1, "喜屋武 香織", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1018, 0, 0, "イオちゃんって呼んでね。", 0, 0, "支倉伊緒です。", 2, 1, "先生って呼ばれるのは\nくすぐったいから", 1, "支倉 伊緒", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1020, 0, 0, "ミミをおいてかないでぇ～", 0, 0, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 2, 1, "あ！/\お兄ちゃ～ん\nまってよ～", 1, "茜 ミミ", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1021, 0, 0, "ふぇぇぇぇぇん……", 0, 0, "あ…あの…えっと…\n栗…林…くるみ…です……", 2, 1, "あの……\nふぇ……", 1, "栗林 くるみ", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1022, 0, 0, "なんてありがとうございます！", 0, 0, "風宮よりです。\nあああああ！", 2, 1, "こんな私に貴重な時間を\n割いていただき、", 1, "風宮 より", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1023, 0, 0, "私こっち行きたいー\nね、早く早くー", 0, 0, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 2, 1, "おにいちゃんどこいくの？\nえ？", 1, "北条 綾音", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1025, 0, 0, "これて何か違う…\nあああすみません！", 0, 0, "わっ…わっ…私、\n天野すずめといいます！", 2, 1, "ふ、不束者ですが\nどうぞ末永く…って、", 1, "天野 すずめ", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1027, 0, 0, "離しませんわ………\n絶対に…!!", 0, 0, "……クスクス…私は\n…倉石恵理子……", 2, 1, "あなたは…運命の……\n伴侶……", 1, "倉石 恵理子", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1028, 0, 0, "…そうでしょ？？", 0, 0, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 2, 1, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1, "佐々木 咲恋", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1029, 0, 0, "あはは、\n私もまだまだだなぁ～", 0, 0, "桜井望だよ！\nよろしくねっ", 2, 1, "ぇっと…\nキミ、私のこと知らないの?!", 1, "桜井 望", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1030, 0, 0, "ショーグン、\nワタシと一緒に天下統一デース！", 0, 0, "デケデケデンっ！", 2, 1, "初めまして、\n私はニノン・ジュベール申すデス！", 1, "ニノン・ジュベール", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1031, 0, 0, "おかしいですね……", 0, 0, "上喜しのぶです。\n手元のドクロが父です。", 2, 1, "でもって私の隣にいるのが……\nえ、見えない？", 1, "上喜 しのぶ", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1033, 0, 0, "そう、\nオラのボケに突っ込める相方が…！", 0, 0, "目指すはビッグな\nお笑い芸人だっぺ！", 2, 1, "けんども\nそれには足りないモンが…", 1, "野戸まひる", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1034, 0, 0, "ちょ\nちょっと一杯飲んできます…！", 0, 0, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 2, 1, "ちょっと緊張しちゃって…", 1, "綾瀬 ゆかり", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1036, 0, 0, "これ以上お話しすることは…\nないです！", 0, 0, "氷川鏡華…です", 2, 1, "知らない人とは話しちゃいけないので", 1, "氷川 鏡華", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1038, 0, 0, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 0, 0, "柏崎…栞です。", 2, 1, "……あ、アラーム。", 1, "柏崎 栞", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1040, 0, 0, "野に咲く花が、\n唯一の話相手です。", 0, 0, "ふ、双葉碧です。", 2, 1, "私、一人も友達がいなくて……", 1, "双葉 碧", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1042, 0, 0, "そう思っています。", 0, 0, "三角千歌です。", 2, 1, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1, "三角 千歌", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1043, 0, 0, "う、疑ってすまなかったな…", 0, 0, "安芸真琴だ。", 2, 1, "あぁ？\nお前のそいつの仲間か？", 1, "安芸 真琴", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1044, 0, 0, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 0, 0, "わらわこそは夜を総べる者！", 2, 1, "生けとし生ける全ての者よ！", 1, "イリヤ・オーンスタイン", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1045, 0, 0, "ｌク、クウカに何かご用ですか!?", 0, 0, "そこで騎士は妖精を乱暴に……", 2, 1, "ぐふふふふ……はっ！", 1, "遠見 空花", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1046, 0, 0, "う～ん…\n猫ってホントに最高にゃ～♪", 0, 0, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 2, 1, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 1, "宮坂たまき", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1048, 0, 0, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 0, 0, "大神美冬よ！", 2, 1, "それでは早速クエストに…", 1, "大神 美冬", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1049, 0, 0, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 0, 0, "星野静流だよ！", 2, 1, "クエストもバトルも\n掃除も洗濯も", 1, "星野静流", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1050, 0, 0, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 0, 0, "アタシは玉泉美咲。", 2, 1, "見ての通りの\nセクシー美少女で", 1, "玉泉美咲", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1052, 0, 0, "？？？？", 0, 0, "？？？", 2, 1, "？？？？", 1, "リマ", 0, 1.4);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1053, 0, 0, "そ、そこまでいうなら\nもらってやる", 0, 0, "モニカ・ヴァイスヴィントだ。", 2, 1, "菓子でつろうなどと\n稚拙な策を……", 1, "モニカ・ヴァイスヴィント", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1058, 0, 0, "そ、そこまでいうなら\nもらってやる", 0, 0, "モニカ・ヴァイスヴィントだ。", 2, 1, "菓子でつろうなどと\n稚拙な策を……", 1, "ペコリーヌ", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1059, 0, 0, "そ、そこまでいうなら\nもらってやる", 0, 0, "モニカ・ヴァイスヴィントだ。", 2, 1, "菓子でつろうなどと\n稚拙な策を……", 1, "コッコロ", 0, 1.5);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1060, 0, 0, "そ、そこまでいうなら\nもらってやる", 0, 0, "モニカ・ヴァイスヴィントだ。", 2, 1, "菓子でつろうなどと\n稚拙な策を……", 1, "キャル", 0, 1.5);
